import{_ as a,c as t,o as i,ah as n}from"./chunks/framework.DaDXF32t.js";const u=JSON.parse('{"title":"C++ TUI Installer Design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-08-02-cpp-tui-installer-design.md","filePath":"superpowers/specs/2026-08-02-cpp-tui-installer-design.md","lastUpdated":1785749755000}'),s={name:"superpowers/specs/2026-08-02-cpp-tui-installer-design.md"};function o(r,e,l,d,c,p){return i(),t("div",null,e[0]||(e[0]=[n(`<h1 id="c-tui-installer-design" tabindex="-1">C++ TUI Installer Design <a class="header-anchor" href="#c-tui-installer-design" aria-label="Permalink to “C++ TUI Installer Design”">​</a></h1><h2 id="_1-goal-and-scope" tabindex="-1">1. Goal and scope <a class="header-anchor" href="#_1-goal-and-scope" aria-label="Permalink to “1. Goal and scope”">​</a></h2><p>Replace the manually packaged Python installer entry point with a native C++ TUI installer that can be built and published by GitHub Actions for:</p><ul><li>Windows x86_64</li><li>Linux x86_64</li><li>macOS x86_64</li><li>macOS arm64</li></ul><p>The feature branch is based directly on <code>upstream/master</code>. The installer owns initial installation, updates, Python runtime and dependency preparation, OCR prebuild installation, configuration migration, launch, and diagnostics. The existing Python installer remains temporarily as a migration reference but is no longer the release entry point.</p><p>The work covers the installer failures collected in <code>Kiramei/baas-tauri#1</code>: unavailable Git/Gitee endpoints, download timeouts, missing requirements, corrupted Git metadata, OCR prebuild download/update failure, and version state being persisted before an update actually succeeds.</p><h2 id="_2-non-goals" tabindex="-1">2. Non-goals <a class="header-anchor" href="#_2-non-goals" aria-label="Permalink to “2. Non-goals”">​</a></h2><ul><li>Do not support the development repository source list (<code>MAIN_REPO_SRC_DEV</code>).</li><li>Do not use <code>https://baas-cdn.kiramei.workers.dev/...</code>; it is known to be unusable.</li><li>Do not replace Git installations with ZIP snapshots when MirrorChyan is not in use.</li><li>Do not add broad test coverage or unrelated refactors.</li><li>Do not store uv, Python, cache, temporary, or installer state outside the BAAS installation root when <code>runtime_path = &quot;default&quot;</code>.</li></ul><h2 id="_3-project-layout-and-dependencies" tabindex="-1">3. Project layout and dependencies <a class="header-anchor" href="#_3-project-layout-and-dependencies" aria-label="Permalink to “3. Project layout and dependencies”">​</a></h2><p>The C++ project lives under <code>deploy/installer</code>:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deploy/installer/</span></span>
<span class="line"><span>├── CMakeLists.txt</span></span>
<span class="line"><span>├── vcpkg.json</span></span>
<span class="line"><span>├── include/baas_installer/</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>└── tests/</span></span></code></pre></div><p>Components are split by responsibility: executable-relative paths, configuration and migration, source ranking, Git CLI, libgit2, MirrorChyan, downloads, repository coordination, transactional deployment, uv environment management, OCR placement, PTY-backed process execution, chunk decoding and redaction, process launch, localization, logging, and TUI presentation.</p><p>Dependencies:</p><ul><li>FTXUI for the terminal interface</li><li>libcurl for HTTP requests, streaming downloads, timeouts, and range probes</li><li>libgit2 as the fallback Git implementation</li><li>toml++ for TOML parsing and editing</li><li>nlohmann/json for MirrorChyan responses, rankings, caches, and transaction journals</li><li>libarchive for ZIP and tar archive extraction</li><li>OpenSSL for TLS and SHA-256 verification</li></ul><p>Dependencies are resolved through a pinned vcpkg manifest. Release binaries use the appropriate static vcpkg triplet where supported.</p><h2 id="_4-configuration-ownership-and-migration" tabindex="-1">4. Configuration ownership and migration <a class="header-anchor" href="#_4-configuration-ownership-and-migration" aria-label="Permalink to “4. Configuration ownership and migration”">​</a></h2><p>There is only one configuration file: <code>setup.toml</code> next to the installer executable. No <code>config.toml</code> is introduced.</p><p>If <code>setup.toml</code> does not exist, the TUI performs the first-run MirrorChyan question before creating it. If the user chooses MirrorChyan, the CDK is entered without echo, validated, and stored only after validation succeeds. The CDK is never written to logs.</p><p>The loader accepts both current and historical forms:</p><ul><li>Current tables: <code>[general]</code>, <code>[paths]</code>, <code>[python]</code>, and <code>[repositories]</code></li><li>Legacy tables: <code>[General]</code>, <code>[URLs]</code>, and <code>[Paths]</code></li><li>Historical aliases including <code>current_BAAS_version</code>, <code>current_BAAS_Cpp_version</code>, <code>current_baas_sha</code>, <code>current_baas_cpp_sha</code>, <code>runtime_path</code>, <code>BAAS_ROOT_PATH</code>, <code>TMP_PATH</code>, and <code>TOOL_KIT_PATH</code></li></ul><p>Current-form fields take precedence. Missing values are read from the legacy form, then from defaults. Unknown tables and keys are preserved. Saving synchronizes the current fields and the legacy compatibility view so both the old GUI and newer service code can read the result. The legacy <code>package_manager</code> value becomes <code>uv</code>.</p><p>In portable mode the persisted path values are relative:</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">baas_root_path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runtime_path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;default&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">General</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runtime_path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;default&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">package_manager = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;uv&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Paths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BAAS_ROOT_PATH = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.&quot;</span></span></code></pre></div><p>All runtime paths are resolved from the actual executable directory, not the process working directory. Configuration writes use a sibling temporary file, flush, atomic replacement, and a last-known-good backup. Repository SHA fields are saved only after repository placement, OCR placement, validation, and dependency synchronization succeed.</p><h2 id="_5-source-lists-ranking-and-fallback" tabindex="-1">5. Source lists, ranking, and fallback <a class="header-anchor" href="#_5-source-lists-ranking-and-fallback" aria-label="Permalink to “5. Source lists, ranking, and fallback”">​</a></h2><h3 id="main-repository" tabindex="-1">Main repository <a class="header-anchor" href="#main-repository" aria-label="Permalink to “Main repository”">​</a></h3><p>The stable source candidates are derived from <code>baas-tauri/crates/baas-updater/src/constants.rs</code>:</p><ol><li>GitHub upstream</li><li>Gitee mirror</li><li>GitCode mirror</li><li>v4 gh-proxy</li><li>v6 gh-proxy</li><li>cdn.gh-proxy.org</li><li>gh-proxy.org</li><li>gh.sevencdn.com</li><li>githubfast.com</li></ol><p><code>MAIN_REPO_SRC_DEV</code> and the custom <code>baas-cdn.kiramei.workers.dev</code> source are excluded.</p><h3 id="ocr-repository" tabindex="-1">OCR repository <a class="header-anchor" href="#ocr-repository" aria-label="Permalink to “OCR repository”">​</a></h3><p>OCR uses <code>pur1fying/BAAS_Cpp_prebuild</code> and its corresponding Gitee and GitHub proxy candidates. The selected platform branch is:</p><ul><li>Windows x86_64: <code>windows-x64</code></li><li>Linux x86_64: <code>linux-x64</code></li><li>macOS x86_64: <code>macos-x64</code></li><li>macOS arm64: <code>macos-arm64</code></li></ul><h3 id="uv-cpython-and-pypi" tabindex="-1">uv, CPython, and PyPI <a class="header-anchor" href="#uv-cpython-and-pypi" aria-label="Permalink to “uv, CPython, and PyPI”">​</a></h3><p>uv binary, CPython download, and PyPI source candidates follow the stable lists in <code>baas-updater</code>, excluding the custom BAAS CDN. User-provided <code>source_list</code> values remain eligible and retain their configured ordering as the initial preference.</p><p>Each source family has an independent ranking persisted under <code>&lt;root&gt;/.baas-installer/source-ranking/</code>. Probing uses a short HEAD request and falls back to a byte-range GET when HEAD is not supported. Ranking records the exact URL set and is discarded if that set changes. Operational failures demote a source and continue with the next candidate. The TUI shows the failed URL, stage, and next fallback without exposing secrets.</p><h2 id="_6-repository-backends-and-update-policy" tabindex="-1">6. Repository backends and update policy <a class="header-anchor" href="#_6-repository-backends-and-update-policy" aria-label="Permalink to “6. Repository backends and update policy”">​</a></h2><p>The main repository and OCR are separate update units. Each unit independently tries this backend order:</p><ol><li>MirrorChyan when a validated CDK is configured</li><li>Installed Git CLI</li><li>Bundled libgit2</li></ol><p>A failure in one unit does not force the other unit to use the same backend. For example, main may use MirrorChyan while OCR falls back to Git CLI. MirrorChyan uses the <code>BAAS_repo</code> resource for main and the platform-specific <code>BAAS_Cpp</code> resource for OCR.</p><h3 id="_6-1-no-op-detection" tabindex="-1">6.1 No-op detection <a class="header-anchor" href="#_6-1-no-op-detection" aria-label="Permalink to “6.1 No-op detection”">​</a></h3><p>The installer reads the expected SHA from <code>setup.toml</code>, but treats the actual local Git <code>HEAD</code> as authoritative when a valid working tree exists. It queries the remote branch tip with the lightweight equivalent of <code>git ls-remote</code> before fetching. If local <code>HEAD</code> equals the remote SHA, the unit is marked complete without <code>fetch</code>, clone, download, or work-tree mutation. If they differ, only then does preparation fetch the required objects. The libgit2 fallback follows the same list-heads-before-fetch rule.</p><p>For MirrorChyan, the installer queries the current resource version first. If the recorded local version is current, it skips the package download. The SHA/version fields in <code>setup.toml</code> are reconciled only after the complete workflow succeeds.</p><h3 id="_6-2-git-update-and-recovery" tabindex="-1">6.2 Git update and recovery <a class="header-anchor" href="#_6-2-git-update-and-recovery" aria-label="Permalink to “6.2 Git update and recovery”">​</a></h3><p>Git CLI is tried against the ranked source list first. Only after Git CLI exhausts every source does libgit2 try the same ranked source list. This preserves the global backend order MirrorChyan &gt; installed Git CLI &gt; bundled libgit2. Git commands disable terminal prompts, credential UI, askpass, and interactive SSH.</p><p>An existing valid repository is updated incrementally: preparation fetches the differing commit without changing the work tree, and deployment hard-resets the selected branch to that commit. The <code>.git</code> directory remains installed. A missing or invalid repository is cloned into staging and deployed as a full replacement while preserving protected user data. This handles installations such as <code>D:\\Amusement\\BAAS_NEW</code>, whose main <code>.git</code> directory contains only <code>objects/</code> and is not a valid repository.</p><p>Successful Git updates intentionally retain the original installer&#39;s hard-reset semantics: uncommitted code changes in the managed repository are discarded. A failed deployment restores the previous committed <code>HEAD</code>, but does not promise to reconstruct pre-existing uncommitted code edits. User configuration and protected data are outside this rule.</p><h3 id="_6-3-mirrorchyan-package-modes" tabindex="-1">6.3 MirrorChyan package modes <a class="header-anchor" href="#_6-3-mirrorchyan-package-modes" aria-label="Permalink to “6.3 MirrorChyan package modes”">​</a></h3><p>Both main and OCR accept full and incremental MirrorChyan ZIP packages. Every package must pass the advertised SHA-256 check before extraction.</p><p>An incremental package must contain a valid <code>changes.json</code> with <code>deleted</code>, <code>added</code>, and <code>modified</code> lists. Paths are normalized after removing the archive&#39;s leading repository directory. Absolute paths, drive-qualified paths, <code>..</code> traversal, and any path resolving outside the target root are rejected. Every added or modified source must exist in staging before the deployment barrier.</p><p>A full package is unpacked to staging and deployed from the archive&#39;s first child directory. If an incremental request temporarily returns a full package, the installer retries the incremental request up to ten times with 500 ms between attempts, then accepts the validated full package returned by the final attempt. After a successful MirrorChyan deployment, the corresponding <code>.git</code> directory is removed transactionally. No Git metadata is removed before commit.</p><h2 id="_7-parallel-preparation-and-ordered-deployment" tabindex="-1">7. Parallel preparation and ordered deployment <a class="header-anchor" href="#_7-parallel-preparation-and-ordered-deployment" aria-label="Permalink to “7. Parallel preparation and ordered deployment”">​</a></h2><p>The main repository and OCR repository are prepared concurrently but never independently committed to the final installation.</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>load/migrate setup.toml</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        +---- prepare main: no-op, Git, or MirrorChyan package --+</span></span>
<span class="line"><span>        |                                                        |</span></span>
<span class="line"><span>        +---- prepare OCR: no-op, Git, or MirrorChyan package ---+--&gt; barrier</span></span>
<span class="line"><span>        |                                                        |</span></span>
<span class="line"><span>        +---- prepare uv/Python assets as dependencies allow ----+</span></span>
<span class="line"><span>                                                                 |</span></span>
<span class="line"><span>                                              deploy main repository</span></span>
<span class="line"><span>                                                                 |</span></span>
<span class="line"><span>                                              deploy OCR repository</span></span>
<span class="line"><span>                                      to core/ocr/baas_ocr_client/bin</span></span>
<span class="line"><span>                                                                 |</span></span>
<span class="line"><span>                                              validate required files</span></span>
<span class="line"><span>                                                                 |</span></span>
<span class="line"><span>                                              synchronize dependencies</span></span>
<span class="line"><span>                                                                 |</span></span>
<span class="line"><span>                                              persist SHAs and launch</span></span></code></pre></div><p>A completed preparation task displays <code>ready; waiting for parallel task</code> until the barrier is satisfied. The commit phase always deploys the main repository first, then OCR into <code>&lt;root&gt;/core/ocr/baas_ocr_client/bin</code>.</p><p>Preparation never modifies the live installation. If either repository exhausts MirrorChyan, Git CLI, libgit2, and source fallbacks, the installer waits for the other task to stop safely, discards both prepared results, and does not enter deployment.</p><p>For an existing Git repository, preparation may fetch objects but must not change the checked-out work tree. Before commit, the installer records old commits and a transaction journal. Git deployment failures restore both repositories to their old committed states. MirrorChyan application backs up affected paths and records additions, modifications, deletions, and <code>.git</code> moves so it can restore the previous installation. <code>setup.toml</code>, the installer executable, user configuration, and logs are protected.</p><p>The commit phase always deploys main before OCR. If either deployment, validation, or uv synchronization fails, the transaction restores every committed unit and leaves the prior SHA/version fields intact. Both SHA/version fields are written together using the atomic configuration-save path only after repository validation and uv synchronization succeed.</p><p>Fresh-install failures remove only files owned by the incomplete transaction. Existing working files remain usable. Stale staging directories are recognized from their journal and safely cleaned or rolled back on the next launch.</p><h2 id="_8-ocr-ownership" tabindex="-1">8. OCR ownership <a class="header-anchor" href="#_8-ocr-ownership" aria-label="Permalink to “8. OCR ownership”">​</a></h2><p>The C++ installer absorbs the desktop OCR prebuild installation and update responsibility currently implemented by <code>core/ocr/baas_ocr_client/server_installer.py</code>.</p><p>After successful OCR placement, it writes an installer-managed marker with the selected platform, backend, and commit or MirrorChyan version. BAAS startup checks this marker and skips the Python network updater, preventing duplicate updates. Existing installations without the marker retain their current Python behavior until the C++ installer completes one successful OCR migration.</p><p>The final OCR executable and libraries must exist directly under <code>core/ocr/baas_ocr_client/bin</code>. That directory remains its own Git working tree in Git mode and contains no <code>.git</code> directory in MirrorChyan mode.</p><h2 id="_9-portable-uv-and-python-environment" tabindex="-1">9. Portable uv and Python environment <a class="header-anchor" href="#_9-portable-uv-and-python-environment" aria-label="Permalink to “9. Portable uv and Python environment”">​</a></h2><p>When <code>runtime_path = &quot;default&quot;</code>, every uv-related path is under the installation root:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;root&gt;/.venv/</span></span>
<span class="line"><span>&lt;root&gt;/tmp/uv/</span></span>
<span class="line"><span>&lt;root&gt;/toolkit/uv/uv[.exe]</span></span>
<span class="line"><span>&lt;root&gt;/toolkit/uv/cache/</span></span>
<span class="line"><span>&lt;root&gt;/toolkit/uv/cpython/</span></span>
<span class="line"><span>&lt;root&gt;/toolkit/uv/python-cache/</span></span>
<span class="line"><span>&lt;root&gt;/toolkit/uv/python-bin/</span></span>
<span class="line"><span>&lt;root&gt;/toolkit/uv/tools/</span></span>
<span class="line"><span>&lt;root&gt;/toolkit/uv/tool-bin/</span></span>
<span class="line"><span>&lt;root&gt;/toolkit/uv/credentials/</span></span>
<span class="line"><span>&lt;root&gt;/toolkit/uv/xdg/{cache,config,data,bin}/</span></span></code></pre></div><p>Every uv process receives explicit <code>UV_CACHE_DIR</code>, <code>UV_PYTHON_INSTALL_DIR</code>, <code>UV_PYTHON_CACHE_DIR</code>, <code>UV_PYTHON_BIN_DIR</code>, <code>UV_TOOL_DIR</code>, <code>UV_TOOL_BIN_DIR</code>, <code>UV_CREDENTIALS_DIR</code>, <code>UV_PROJECT_ENVIRONMENT</code>, <code>XDG_CACHE_HOME</code>, <code>XDG_CONFIG_HOME</code>, <code>XDG_DATA_HOME</code>, <code>XDG_BIN_HOME</code>, and platform temporary-directory variables. It also receives <code>UV_NO_CONFIG=1</code>, <code>UV_PYTHON_INSTALL_REGISTRY=0</code>, and <code>UV_VENV_RELOCATABLE=1</code>.</p><p>The installer downloads a platform-specific uv binary, uses uv to install the configured Python 3.9 release, creates <code>&lt;root&gt;/.venv</code> as relocatable, compiles the applicable requirements file to an installer-managed lock, and performs <code>uv pip sync</code>. A SHA-256 cache over the requirements input, generated lock, Python version, and PyPI URL skips unchanged dependency work. Missing requirements are detected before deployment is finalized.</p><p>Custom <code>runtime_path</code> values are preserved and bypass installer-managed uv/Python setup.</p><h2 id="_10-process-capture-tui-localization-and-diagnostics" tabindex="-1">10. Process capture, TUI, localization, and diagnostics <a class="header-anchor" href="#_10-process-capture-tui-localization-and-diagnostics" aria-label="Permalink to “10. Process capture, TUI, localization, and diagnostics”">​</a></h2><h3 id="_10-1-pty-process-execution" tabindex="-1">10.1 PTY process execution <a class="header-anchor" href="#_10-1-pty-process-execution" aria-label="Permalink to “10.1 PTY process execution”">​</a></h3><p>Every user-visible external command runs through a pseudo-terminal: ConPTY on Windows and <code>forkpty</code>/<code>openpty</code> on Linux and macOS. This includes Git clone/fetch operations, uv, and any external archive or download helper. Output is consumed as arbitrary byte chunks instead of line-oriented stdout/stderr pipes, so tools retain terminal-aware progress output.</p><p>Small machine-readable probes such as Git <code>rev-parse</code>, <code>ls-remote</code>, and tool <code>--version</code> may use hidden captured pipes. They never write their raw output to the TUI and must remain non-interactive.</p><p>Each PTY stream has an incremental decoder that buffers incomplete UTF-8 sequences, removes ANSI CSI and OSC control sequences, applies backspace, replaces the current logical line on carriage return, and commits it on newline. A carriage-return progress update therefore replaces the final displayed line instead of flooding the history. The same normalized event stream feeds the TUI and disk log.</p><h3 id="_10-2-unified-tui" tabindex="-1">10.2 Unified TUI <a class="header-anchor" href="#_10-2-unified-tui" aria-label="Permalink to “10.2 Unified TUI”">​</a></h3><p>The first-run page asks whether MirrorChyan is available and validates the optional CDK. During work, the interface remains in one full TUI view with static task states: waiting, checking, downloading, applying, complete, or failed. It shows percentages only when a real measurable total exists. There is no spinner, animated running glyph, dedicated Git panel, or normal-success page.</p><p>All process output appears in one large installation-log region. Each logical line is tagged with time, task, backend, and severity. The view follows the tail by default and supports scrolling through history. Git carriage-return progress is mixed into this same log using the replacement behavior above.</p><p>Failures offer retry, the next backend where applicable, and exit. Escape requests cancellation during preparation. Once a commit step starts, cancellation waits for the current atomic step or rollback rather than terminating mid-write.</p><p>After installation commits successfully, launch failure does not roll back the installed version. The TUI reports the launch failure and permits another launch attempt. As soon as BAAS starts successfully, the installer exits immediately without displaying a success screen or requiring an Exit action.</p><h3 id="_10-3-chinese-and-english" tabindex="-1">10.3 Chinese and English <a class="header-anchor" href="#_10-3-chinese-and-english" aria-label="Permalink to “10.3 Chinese and English”">​</a></h3><p>Installer-owned strings live in a two-language message catalog. Windows selects the language from the system UI locale. Linux and macOS inspect <code>LC_ALL</code>, then <code>LC_MESSAGES</code>, then <code>LANG</code>. A case-insensitive locale whose normalized language prefix is <code>zh</code> selects Simplified Chinese, including both <code>zh-CN</code> and <code>zh_CN</code> forms; all other or unknown locales select English. There is no manual language selector. Native child-process output is retained, while installer prefixes, statuses, diagnostics, and actions use the selected language.</p><h3 id="_10-4-secret-handling-and-persistent-logs" tabindex="-1">10.4 Secret handling and persistent logs <a class="header-anchor" href="#_10-4-secret-handling-and-persistent-logs" aria-label="Permalink to “10.4 Secret handling and persistent logs”">​</a></h3><p>Logs and crash diagnostics are written under <code>&lt;root&gt;/log/installer.log</code>. A single redaction layer runs before any event reaches either the TUI or disk. It removes the known CDK, <code>cdk</code> query values, authorization headers, and cookie values. MirrorChyan requests use in-process libcurl, so the CDK is never placed in a child-process command line, PTY stream, or environment dump.</p><p>The operator-provided secret file outside the worktree is test input only. Tests receive its path through a local-only test setting and read it directly at runtime without printing the path or contents, copying, committing, embedding, or passing its contents on a command line. Test completion scans logs, diffs, and artifacts for the secret bytes and reports only pass/fail.</p><h2 id="_11-build-and-release-automation" tabindex="-1">11. Build and release automation <a class="header-anchor" href="#_11-build-and-release-automation" aria-label="Permalink to “11. Build and release automation”">​</a></h2><p>The branch starts from the current <code>upstream/master</code>. GitHub Actions builds with fixed runner labels:</p><ul><li><code>windows-2025</code>, x86_64</li><li><code>ubuntu-24.04</code>, x86_64</li><li><code>macos-15-intel</code>, x86_64</li><li><code>macos-15</code>, arm64</li></ul><p>Pull requests and <code>workflow_dispatch</code> build, run the focused tests, and upload temporary Actions artifacts. A manual input may explicitly request a Release for a supplied tag.</p><p>Pushing a <code>v*</code> tag builds all four targets, calculates SHA-256 hashes, creates or updates the matching GitHub Release, and uploads the executables plus <code>SHA256SUMS</code> as Release Assets. Windows keeps the compatible pattern <code>BlueArchiveAutoScript_&lt;version&gt;_win_x86_64.exe</code>; all other assets include OS and architecture. Release publishing uses <code>contents: write</code> and is idempotent for an existing tag Release.</p><h2 id="_12-failure-handling-and-verification" tabindex="-1">12. Failure handling and verification <a class="header-anchor" href="#_12-failure-handling-and-verification" aria-label="Permalink to “12. Failure handling and verification”">​</a></h2><h3 id="_12-1-failure-rules" tabindex="-1">12.1 Failure rules <a class="header-anchor" href="#_12-1-failure-rules" aria-label="Permalink to “12.1 Failure rules”">​</a></h3><ul><li>Preparation performs no live installation changes. Failure of one repository joins the other task safely and discards all staging work.</li><li>MirrorChyan failure falls back only the affected repository through Git CLI, libgit2, and ranked sources. The installer fails only after that unit exhausts every permitted path.</li><li>Packages are rejected before the barrier on checksum, manifest, missing-source, or path-safety failure.</li><li>Deployment is journaled and ordered main then OCR. Any deployment, validation, or uv failure restores prior files and committed Git heads and does not persist new SHA/version state.</li><li>Child processes are non-interactive, cancellable where safe, and subject to stage-specific timeouts.</li><li>A BAAS launch failure leaves the successfully installed version committed. A successful launch causes immediate installer exit.</li></ul><h3 id="_12-2-automated-tests" tabindex="-1">12.2 Automated tests <a class="header-anchor" href="#_12-2-automated-tests" aria-label="Permalink to “12.2 Automated tests”">​</a></h3><p>Automated tests cover these risky contracts:</p><ul><li>Legacy/current mixed <code>setup.toml</code> migration and unknown-field preservation</li><li>Source ranking, URL-set invalidation, and per-repository backend fallback order</li><li>A local Git <code>HEAD</code> equal to the remote branch performs no fetch, clone, or work-tree mutation</li><li>A changed remote branch fetches incrementally, retains <code>.git</code>, and updates the stored SHA only after success</li><li>Missing or corrupt Git metadata selects full clone; failed deployment restores the previous committed state</li><li>Parallel preparation barrier with main-before-OCR deployment order</li><li>MirrorChyan full and incremental packages for both main and OCR, including additions, modifications, deletions, checksum failure, manifest failure, path traversal rejection, and transactional <code>.git</code> removal</li><li>Incremental-package request receiving a full package follows bounded retry and validated full-package fallback</li><li>PTY decoding for split UTF-8, CSI/OSC sequences, carriage-return replacement, newline commit, and backspace</li><li>Unified log tagging, tail following, scrolling, redaction, and identical normalized TUI/disk events</li><li>Windows, Linux, and macOS locale detection; Chinese and English render snapshots; absence of spinner UI</li><li>Successful launch exits immediately; launch failure remains in the TUI without rolling back installation</li><li>Executable-relative and portable uv path calculation</li></ul><h3 id="_12-3-local-integration-and-migration-tests" tabindex="-1">12.3 Local integration and migration tests <a class="header-anchor" href="#_12-3-local-integration-and-migration-tests" aria-label="Permalink to “12.3 Local integration and migration tests”">​</a></h3><p>Temporary local Git remotes prove both no-op and real incremental updates without depending on upstream movement. The no-op case must record that no fetch command was issued. The update case must prove concurrent preparation, main-before-OCR deployment, retained Git metadata, and atomic SHA persistence.</p><p>MirrorChyan integration tests use the operator-provided secret file only when explicitly configured. They exercise the real main and OCR resource APIs and downloads in disposable staging or an isolated installation copy. The tests verify full/incremental behavior where the service exposes those versions, package checksums, placement, and fallback. A final byte-for-byte secret scan covers the repository diff, installer logs, test output captured on disk, staging metadata, and build artifacts; neither the secret nor its local path is printed.</p><p>End-to-end Windows migration uses a fresh copy of <code>D:\\Amusement\\BAAS_NEW</code>; the original directory is never modified. The test must prove that corrupt Git metadata is rebuilt, the old configuration is migrated, user data remains, OCR is placed under <code>core/ocr/baas_ocr_client/bin</code>, uv replaces the managed pip environment, all uv data remains within the copied installation, and BAAS launches.</p><p>The completed copy is then moved as a whole into <code>E:\\tmp</code>. Verification runs uv path queries, the moved <code>.venv</code> interpreter, representative dependency imports, and BAAS startup. It also scans portable metadata and launch files for references to the old installation path. Success requires operation from the new location after the old copied location is absent.</p><p>Cross-platform CI builds and runs focused tests on Windows x86_64, Linux x86_64, macOS x86_64, and macOS arm64. Runtime installation is exercised locally on Windows and through safe CI smoke tests that do not require a real MirrorChyan CDK.</p>`,100)]))}const m=a(s,[["render",o]]);export{u as __pageData,m as default};
